            "Велика вибірка не виправляє неправильно визначеного показника. Якщо «розуміння» виміряли натисканням кнопки завершення, точна оцінка частоти натискань усе ще не є оцінкою глибокого засвоєння. Перш ніж обирати складніший метод, перевір поняття, дизайн і те, які спостереження потрапили до даних. Методологічний аргумент починається раніше за розрахунок."
