      "whyUk": "Критичне мислення — це робота з підставами власного висновку. Воно потрібне для чесного порівняння шкіл і для того, щоб переконлива історія не замінювала перевірки.",
      "openingQuestionUk": "Вигаданий автор каже: «Ця теорія правдива, бо її заперечують лише ті, хто не готовий побачити правду про себе». Що могло б за таких умов спростувати його думку?",
