            "Аргумент поєднує засновки (premises) з висновком. Засновок — твердження, яке пропонують як підставу; висновок — те, що ним обґрунтовують. Не кожна послідовність переконливих речень утворює добрий аргумент. Спершу віднови пропущені кроки: чому саме наведена подія повинна підтримувати саме цей висновок?",
            "У вигаданій фразі «метод популярний, отже ефективний» прихований засновок пов’язує популярність з ефективністю. Його треба окремо обґрунтувати. Популярність може бути пов’язана з доступністю, рекламою або привабливою історією. Визначення прихованого засновку перетворює суперечку з обміну впевненістю на перевірюване питання про підстави."
