            "Не слід плутати «я поки не знаю іншого пояснення» з «інших пояснень немає». У складній ситуації спочатку можна скласти кілька варіантів і визначити, які дані їх розрізняють. Оцінюй не лише здатність теорії переказати вже відоме, а й точність її майбутніх прогнозів. Дотепна інтерпретація після події має інший статус, ніж наперед визначений тест."
