            "Для підсумкового аналізу обери тезу, випиши засновки, тип підстави та найсильнішу альтернативу. Познач рівень упевненості словами, прив’язаними до конкретних обмежень, а не довільним рейтингом. Заверши даними, які могли б змінити висновок. Мета — не безкінечно сумніватися в усьому, а сформувати позицію, здатну витримувати перевірку й відповідально змінюватися."
